def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        if i == n:
            # End of line
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < n and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows
                        if i < n:
                            if line[i] == ',':
                                i += 1
                                fields.append(''.join(field))
                                continue
                            else:
                                # Malformed: closing quote not followed by comma or end
                                return None
                        else:
                            # End of line after closing quote
                            fields.append(''.join(field))
                            break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Double quote not allowed in unquoted field
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))

            if i < n and line[i] == ',':
                i += 1
            else:
                break

    return fields

